using MallEnergyBilling.Web.Models;using MallEnergyBilling.Web.Services;namespace MallEnergyBilling.Tests;
public class BillingTests{readonly BillingCalculator calc=new();[Fact]public void CalculatesCompleteInvoice(){var r=calc.Calculate(new(100,150,.22m,5,2,11,3,10));Assert.Equal(50,r.Consumption);Assert.Equal(11,r.EnergyCharge);Assert.Equal(1.98m,r.Tax);Assert.Equal(26.98m,r.Total);}[Fact]public void RejectsLowerClosingReading()=>Assert.Throws<InvalidOperationException>(()=>calc.Calculate(new(20,19,1,0,0,0,0,0)));[Fact]public void CalculatesFixedTaxDiscountAndBalance(){var r=calc.Calculate(new(0,10,1,5,0,10,2,4));Assert.Equal(18.5m,r.Total);}[Fact]public void ConvertsHighLowWords(){Assert.Equal(125345u,ModbusConverter.UInt32(1,59809,WordOrder.HighLow));}[Fact]public void ConvertsLowHighWords(){Assert.Equal(125345u,ModbusConverter.UInt32(59809,1,WordOrder.LowHigh));}[Fact]public void AppliesScaling()=>Assert.Equal(1253.45m,ModbusConverter.Scale(125345,.01m));[Fact]public void DecimalAvoidsFloatingPointError()=>Assert.Equal(.03m,calc.Calculate(new(0,.3m,.1m,0,0,0,0,0)).EnergyCharge);}
